import{_ as s,a0 as p,w as r,s as l,I as n,x as t,a1 as i,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux有問必答：如何在Linux下禁用IPv6 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux下禁用IPv6 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux下禁用IPv6 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux下禁用IPv6 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux","title":"Linux有問必答：如何在Linux下禁用IPv6","tag":"201505","desc":""},"relativePath":"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux.md","filePath":"[post].md"}'),u={name:"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux.md"};function v(P,e,c,h,I,x){const o=p("Link");return r(),l("div",null,[e[16]||(e[16]=n("h1",{id:"linux有問必答-如何在linux下禁用ipv6",tabindex:"-1"},[t("Linux有問必答：如何在Linux下禁用IPv6 "),n("a",{class:"header-anchor",href:"#linux有問必答-如何在linux下禁用ipv6","aria-label":"Permalink to “Linux有問必答：如何在Linux下禁用IPv6”"},"​")],-1)),e[17]||(e[17]=n("blockquote",null,[n("p",null,[n("strong",null,"問題"),t("：我發現我的一個應用程序在嘗試通過IPv6建立連接，但是由於我們本地網絡不允許分配IPv6的流量，IPv6連接會超時，應用程序的連接會回退到IPv4，這樣就會造成不必要的延遲。由於我目前對IPv6沒有任何需求，所以我想在我的Linux主機上禁用IPv6。有什麼比較合適的方法呢？")])],-1)),e[18]||(e[18]=n("p",null,"IPv6被認為是IPv4——互聯網上的傳統32位地址空間——的替代產品，它用來解決現有IPv4地址空間即將耗盡的問題。然而，由於已經有大量主機、設備用IPv4連接到了互聯網上，所以想在一夜之間將它們全部切換到IPv6幾乎是不可能的。許多IPv4到IPv6的轉換機制(例如：雙協議棧、網絡隧道、代理) 已經被提出來用來促進IPv6能被採用，並且很多應用也正在進行重寫，如我們所提倡的，來增加對IPv6的支持。有一件事情可以確定，就是在可預見的未來裏IPv4和IPv6勢必將共存。",-1)),n("p",null,[e[1]||(e[1]=t("理想情況下，",-1)),i(o,{href:"http://www.google.com/intl/en/ipv6/statistics.html"},{default:a(()=>[...e[0]||(e[0]=[t("向IPv6過渡的進程",-1)])]),_:1}),e[2]||(e[2]=t("不應該被最終的用户所看見，但是IPv4/IPv6混合環境有時會讓你碰到各種源於IPv4和IPv6之間不經意間的相互碰撞的問題。舉個例子，你會碰到應用程序超時的問題，比如apt-get或ssh嘗試通過IPv6連接失敗、DNS服務器意外清空了IPv6的AAAA記錄、或者你支持IPv6的設備不兼容你的互聯網服務提供商遺留下的IPv4網絡，等等等等。",-1))]),e[19]||(e[19]=d(`<p>當然這不意味着你應該盲目地在你的Linux機器上禁用IPv6。鑑於IPv6許諾的種種好處，作為社會的一份子我們最終還是要充分擁抱它的，但是作為給最終用户進行故障排除過程的一部分，如果IPv6確實是罪魁禍首，那你可以嘗試去關閉它。</p><p>這裏有一些讓你在Linux中部分(例如：對於某個特定的網絡接口)或全部禁用IPv6的小技巧。這些小貼士應該適用於所有主流的Linux發行版包括Ubuntu、Debian、Linux Mint、CentOS、Fedora、RHEL以及Arch Linux。</p><h3 id="查看ipv6在linux中是否被啓用" tabindex="-1">查看IPv6在Linux中是否被啓用 <a class="header-anchor" href="#查看ipv6在linux中是否被啓用" aria-label="Permalink to “查看IPv6在Linux中是否被啓用”">​</a></h3><p>所有現代Linux發行版默認都自動啓用IPv6。為了能看到IPv6在你的Linux中是否被激活，可以使用ifconfig或ip命令。如果你在輸入這些命令之後看到&quot;inet6&quot;字樣的輸出，那就意味着你的Linux系統啓用了IPv6。</p><pre><code>$ ifconfig 
</code></pre><p><img src="https://farm8.staticflickr.com/7282/16415082398_5fb0920506_b.jpg" alt=""></p><pre><code>$ ip addr 
</code></pre><p><img src="https://farm8.staticflickr.com/7290/16415082248_c4e075548b_c.jpg" alt=""></p><h3 id="臨時禁用ipv6" tabindex="-1">臨時禁用IPv6 <a class="header-anchor" href="#臨時禁用ipv6" aria-label="Permalink to “臨時禁用IPv6”">​</a></h3><p>如果你想要在你的Linux系統上臨時關閉IPv6，你可以用 /proc 文件系統。&quot;臨時&quot;的意思是我們所做的禁用IPv6的更改在系統重啓後將不被保存。IPv6會在你的Linux機器重啓後再次被啓用。</p><p>要將一個特定的網絡接口禁用IPv6，使用以下命令：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/&lt;interface-name&gt;/disable_ipv6&#39; 
</code></pre><p>舉個例子，將eth0接口禁用IPv6：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/eth0/disable_ipv6&#39; 
</code></pre><p><img src="https://farm8.staticflickr.com/7288/15982511863_0c1feafe7f_b.jpg" alt=""></p><p>重新啓用eth0接口的IPv6：</p><pre><code>$ sudo sh -c &#39;echo 0 &gt; /proc/sys/net/ipv6/conf/eth0/disable_ipv6&#39; 
</code></pre><p>如果你想要將整個系統所有接口包括迴環接口禁用IPv6，使用以下命令：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/all/disable_ipv6&#39; 
</code></pre><h3 id="永久禁用ipv6" tabindex="-1">永久禁用IPv6 <a class="header-anchor" href="#永久禁用ipv6" aria-label="Permalink to “永久禁用IPv6”">​</a></h3><p>以上方法是不能永久禁用IPv6的，你一旦重啓系統IPv6還是會被啓用。如果你想要永久關閉它，有幾個方法你可以試試。</p><h4 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h4><p>第一種方法是通過 /etc/sysctl.conf 文件對 /proc 進行永久修改。</p><p>換句話説，就是用文本編輯器打開 /etc/sysctl.conf 然後添加以下內容：</p><pre><code># 禁用整個系統所有接口的IPv6
net.ipv6.conf.all.disable_ipv6 = 1

# 禁用某一個指定接口的IPv6(例如：eth0, lo)
net.ipv6.conf.lo.disable_ipv6 = 1
net.ipv6.conf.eth0.disable_ipv6 = 1
</code></pre><p>在 /etc/sysctl.conf 使這些更改生效，運行以下命令：</p><pre><code>$ sudo sysctl -p /etc/sysctl.conf 
</code></pre><p>或者直接重啓。</p><h4 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h4><p>另一個永久禁用IPv6的方法是在開機的時候傳遞一個必要的內核參數。</p><p>用文本編輯器打開 /etc/default/grub 並給GRUB_CMDLINE_LINUX變量添加&quot;ipv6.disable=1&quot;。</p><pre><code>$ sudo vi /etc/default/grub
</code></pre><hr><pre><code>GRUB_CMDLINE_LINUX=&quot;xxxxx ipv6.disable=1&quot;
</code></pre><p>上面的&quot;xxxxx&quot;代表任何已有的內核參數，在它後面添加&quot;ipv6.disable=1&quot;。</p><p><img src="https://farm8.staticflickr.com/7286/15982512103_ec5d940e58_b.jpg" alt=""></p><p>最後，不要忘記用以下方法保存對GRUB/GRUB2的修改：</p><p>Debian、Ubuntu或Linux Mint系統：</p><pre><code>$ sudo update-grub 
</code></pre><p>Fedora、CentOS/RHEL系統：</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg 
</code></pre><p>現在只要你重啓你的Linux系統，IPv6就會完全被禁用。</p><h3 id="禁用ipv6之後的其它可選步驟" tabindex="-1">禁用IPv6之後的其它可選步驟 <a class="header-anchor" href="#禁用ipv6之後的其它可選步驟" aria-label="Permalink to “禁用IPv6之後的其它可選步驟”">​</a></h3><p>這裏有一些在你禁用IPv6後需要考慮的可選步驟，這是因為當你在內核裏禁用IPv6後，其它程序也許仍然會嘗試使用IPv6。在大多數情況下，應用程序的這種行為不太會影響到什麼，但是出於效率或安全方面的原因，你可以為他們禁用IPv6。</p><h4 id="etc-hosts" tabindex="-1">/etc/hosts <a class="header-anchor" href="#etc-hosts" aria-label="Permalink to “/etc/hosts”">​</a></h4><p>根據你的設置， /etc/hosts 會包含一條或多條IPv6的hosts和它們的地址。用文本編輯器打開 /etc/hosts 並註釋掉包含IPv6 hosts的腳本行。</p><pre><code>$ sudo vi /etc/hosts
</code></pre><hr><pre><code># comment these IPv6 hosts
# ::1     ip6-localhost ip6-loopback
# fe00::0 ip6-localnet
# ff00::0 ip6-mcastprefix
# ff02::1 ip6-allnodes
# ff02::2 ip6-allrouters
</code></pre><h4 id="network-manager" tabindex="-1">Network Manager <a class="header-anchor" href="#network-manager" aria-label="Permalink to “Network Manager”">​</a></h4><p>如果你在用NetworkManager來管理你的網絡設置，你可以在NetworkManager裏禁用IPv6。在NetworkManager打開wired connection，點擊&quot;IPv6 Settings&quot;選項並在&quot;Method&quot;一欄選擇&quot;Ignore&quot;，保存退出。</p><p><img src="https://farm8.staticflickr.com/7293/16394993017_21917f027b_o.png" alt=""></p><h4 id="ssh服務" tabindex="-1">SSH服務 <a class="header-anchor" href="#ssh服務" aria-label="Permalink to “SSH服務”">​</a></h4><p>默認情況下，OpenSSH服務(sshd)會去嘗試捆綁IPv4和IPv6的地址。</p><p>要強制sshd只捆綁IPv4地址，用文本編輯器打開 /etc/ssh/sshd_config 並添加以下行。inet只適用於IPv4，而inet6是適用於IPv6的。</p><pre><code>$ sudo vi /etc/ssh/sshd_config
</code></pre><hr><pre><code>AddressFamily inet
</code></pre><p>然後重啓sshd服務。</p><hr>`,60)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/disable-ipv6-linux.html"},{default:a(()=>[...e[3]||(e[3]=[t("http://ask.xmodulo.com/disable-ipv6-linux.html",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("作者：",-1)),i(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:a(()=>[...e[5]||(e[5]=[t("Dan Nanni",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),i(o,{href:"https://github.com/ZTinoZ"},{default:a(()=>[...e[6]||(e[6]=[t("ZTinoZ",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:a(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const L=s(u,[["render",v]]);export{b as __pageData,L as default};
